import * as RadioGroupPrimitive from "@rn-primitives/radio-group";
import type { ComponentProps } from "react";
import { View } from "react-native";
import { cn } from "../../lib/utils.js";

/** Extra touch area around the 20pt dot, in points. */
const HIT_SLOP = 10;

/** Props for {@link RadioGroup}. */
export type RadioGroupProps = ComponentProps<typeof RadioGroupPrimitive.Root>;

/**
 * A set of mutually exclusive options.
 *
 * Controlled only: pass `value` and `onValueChange`. Exactly one item can be
 * selected, which is what separates this from a list of checkboxes.
 * @param props - {@link RadioGroupProps}
 * @returns The radio group root
 * @example
 * ```tsx
 * <RadioGroup value={plan} onValueChange={setPlan}>
 *   <View className="flex-row items-center gap-2">
 *     <RadioGroupItem value="free" aria-labelledby="plan-free" />
 *     <Label nativeID="plan-free">Free</Label>
 *   </View>
 * </RadioGroup>
 * ```
 */
export function RadioGroup({ className, ...props }: RadioGroupProps) {
	return <RadioGroupPrimitive.Root className={cn("gap-3", className)} {...props} />;
}

/** Props for {@link RadioGroupItem}. */
export type RadioGroupItemProps = ComponentProps<typeof RadioGroupPrimitive.Item>;

/**
 * One option in a {@link RadioGroup}.
 *
 * Pair each item with a Label through `aria-labelledby` — the dot alone has
 * no accessible name, and the label also enlarges the tap area.
 * @param props - {@link RadioGroupItemProps}
 * @returns The radio item
 */
export function RadioGroupItem({ className, ...props }: RadioGroupItemProps) {
	return (
		<RadioGroupPrimitive.Item
			hitSlop={HIT_SLOP}
			className={cn(
				"h-5 w-5 shrink-0 items-center justify-center rounded-full border border-input",
				props.disabled && "opacity-50",
				className,
			)}
			{...props}
		>
			<RadioGroupPrimitive.Indicator className="items-center justify-center">
				<View className="h-2.5 w-2.5 rounded-full bg-primary" />
			</RadioGroupPrimitive.Indicator>
		</RadioGroupPrimitive.Item>
	);
}

import { createContext, useContext } from "react";

/**
 * Class names a parent wants applied to the `<Text>` elements inside it.
 *
 * React Native text does not inherit colour or size from its container the
 * way DOM text does, so a `Button` cannot make its label
 * `text-primary-foreground` by styling itself. Instead it provides that
 * class here and `Text` reads it. Same pattern React Native Reusables
 * uses; kept as a tiny shared module so every component agrees on it.
 */
export const TextClassContext = createContext<string | undefined>(undefined);

/**
 * Read the class names the nearest text-styling ancestor provided.
 * @returns The inherited class string, or undefined outside any provider
 */
export function useTextClass(): string | undefined {
	return useContext(TextClassContext);
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind-aware conflict resolution.
 *
 * Deliberately a copy of the web helper rather than an import from
 * `@hex-core/components`: that package is React DOM, and `hex add` ships
 * this file into the consumer's project alongside each component anyway.
 * NativeWind's platform prefixes (`ios:`, `android:`, `native:`) are
 * unknown to tailwind-merge and pass through untouched.
 * @param inputs - Class values (strings, arrays, conditionals) to merge
 * @returns The merged class string with later Tailwind utilities winning
 */
export function cn(...inputs: ClassValue[]): string {
	return twMerge(clsx(inputs));
}
